      "instructionsEn": "Write 2-3 English sentences using could: a suggestion for tonight or the weekend, something you think may be true but are not sure about, and something you could have done in the past but did not do (could have + past participle).",
      "ruleSummary": "This unit practises could (do) and could have (done). Besides being the past of can, could suggests a possible action now or in the future (What shall we do tonight? We could go to the cinema), where can is also possible but sounds more certain. could, not can, is used for unrealistic actions (I'm so tired, I could sleep for a week) and for what is possible in this particular situation now or later (The story could be true; The weather could change later, versus the general The weather can change quickly in the mountains). could have (done) moves all of that into the past, and often means it was possible but did not happen (You could have stayed with me). couldn't means it would not be possible (I couldn't live in a big city) as well as I was not able to; couldn't have (done) means it would not have been possible (It couldn't have been better). A correct student sentence must use could + base verb, or could have + past participle for the past, and must not use can where the meaning is unreal or situation-specific."
