      "instructionsEn": "Write 2-3 English sentences about plans you have not fixed yet, using may or might (and may not / might not). You can add one sentence with might as well.",
      "ruleSummary": "This unit practises may and might for the future. I may/might do something means perhaps I will do it, and contrasts with I'm going to, which is a decision already made (I may buy a car versus I'm going to buy a car). The negatives are may not and might not. may and might are interchangeable except when the situation is unreal, where only might is used (If they paid me better, I might work harder, not I may work). may/might be -ing describes an activity possibly in progress at a future time, or an unfixed plan (I might be going to Ireland soon). might/may as well means we should do it because there is no better alternative (We've missed the bus, we might as well walk). A correct student sentence must use a bare infinitive after may/might, must express an unfixed possibility rather than a decision already taken, and must not use may in an unreal if-sentence."
