      "instructionsEn": "Write 2-3 English sentences: a piece of advice for a friend (should), and something in the past you should have done or shouldn't have done (should have / shouldn't have + past participle).",
      "ruleSummary": "This unit practises should. You should do something means it is a good or right thing to do, and is used for advice and opinions (You look tired, you should go to bed), often with I think / I don't think / Do you think ...?. shouldn't is the negative. should is weaker than must or have to. should is also used when something is not what we expect, or when we expect something to happen (She should be here by now; She's studied hard, so she should pass; It shouldn't be hard to find a hotel). should have + past participle means it did not happen but would have been a good idea (You should have come); shouldn't have + past participle means it did happen and was not a good idea (I shouldn't have eaten so much). ought to (with to) can replace should throughout. A correct student sentence must use a bare infinitive after should, should have + past participle for the past, and must not use should have for something still in the future."
