      "instructionsEn": "Write 2-3 English sentences with if: one about something that really may happen (if + present, will), and one imagining something you do not expect to happen (if + past, would).",
      "ruleSummary": "This unit practises if I do versus if I did. if + present + will describes something the speaker thinks may really happen (If we take the bus, it will be cheaper). if + PAST + would describes something that will not happen, or that the speaker does not expect (If we took the bus, it would be cheaper, but we're taking the train; What would you do if you won a lot of money?; If there was an election tomorrow, who would you vote for?). The past form here has a present or future meaning, not a past one. would is not used in the if-clause itself, only in the main clause (I'd be scared if somebody pointed a gun at me, not if somebody would point), and could or might can replace would in the main clause (If I won a lot of money, I might buy a house). A correct student sentence must keep will/would out of the if-clause and must match the pair: present + will for a real possibility, past + would for an imagined one."
